style.css:
@-moz-document domain("roblox.com") {
html, body {
    background: url("https://i.ibb.co/kghdWTyp/822c23d2e9163f9fbe0c8da238055432.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  .container-main,
  .game-detail-page,
  .section,
  .rbx-body,
  .content,
  .navbar,
  .footer,
  .header,
  .container-header,
  .main-content {
    background: transparent !important;
    backdrop-filter: blur(4px);
  }
}
